import {
  doublePrecision,
  index,
  jsonb,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";

import type { ExtraColumn } from "../zod-schemas";
import { user } from "./auth-schema";

// Better Auth tables — generated by `npx @better-auth/cli generate`.
// Re-exported here so drizzle-kit picks them up from the single schema entry.
// Do not edit auth-schema.ts by hand: regenerate it instead.
export * from "./auth-schema";

// Archivio dell'utente (modello B: salvataggio esplicito da ricerca esterna).
// Una lista = una "tipologia di ricerca" ("pizzerie grugliasco"); gli item
// sono snapshot dei risultati Google Places + note + campi custom utente (extra).

export const savedList = pgTable(
  "saved_list",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    kind: text("kind", { enum: ["company", "job"] }).notNull(),
    /** Nome visibile ("pizzerie grugliasco") — unico per utente+tipo. */
    name: text("name").notNull(),
    /** Registro colonne custom: le chiavi vivono dentro item.extra. */
    columns: jsonb("columns").$type<ExtraColumn[]>().notNull().default([]),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .notNull()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    index("saved_list_user_idx").on(t.userId),
    unique("saved_list_user_kind_name_key").on(t.userId, t.kind, t.name),
  ],
);

export const savedCompany = pgTable(
  "saved_company",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    listId: uuid("list_id")
      .notNull()
      .references(() => savedList.id, { onDelete: "cascade" }),
    /** Google place_id — dedupe dentro la lista. */
    externalId: text("external_id").notNull(),
    name: text("name").notNull(),
    type: text("type").notNull(),
    comune: text("comune").notNull(),
    address: text("address").notNull(),
    province: text("province"),
    phone: text("phone"),
    website: text("website"),
    lat: doublePrecision("lat").notNull(),
    lon: doublePrecision("lon").notNull(),
    notes: text("notes"),
    /** Valori delle colonne custom della lista (key → valore testuale). */
    extra: jsonb("extra").$type<Record<string, string>>().notNull().default({}),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .notNull()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    index("saved_company_list_idx").on(t.listId),
    unique("saved_company_list_external_key").on(t.listId, t.externalId),
  ],
);

export const savedJobOffer = pgTable(
  "saved_job_offer",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    listId: uuid("list_id")
      .notNull()
      .references(() => savedList.id, { onDelete: "cascade" }),
    /** htidocid Google Jobs — dedupe dentro la lista. */
    externalId: text("external_id").notNull(),
    title: text("title").notNull(),
    companyName: text("company_name").notNull(),
    location: text("location").notNull(),
    via: text("via").notNull(),
    description: text("description").notNull(),
    applyLink: text("apply_link").notNull(),
    notes: text("notes"),
    extra: jsonb("extra").$type<Record<string, string>>().notNull().default({}),
    createdAt: timestamp("created_at", { withTimezone: true })
      .defaultNow()
      .notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .defaultNow()
      .notNull()
      .$onUpdate(() => new Date()),
  },
  (t) => [
    index("saved_job_offer_list_idx").on(t.listId),
    unique("saved_job_offer_list_external_key").on(t.listId, t.externalId),
  ],
);
